// TypeScript data models and a simple router skeleton
interface Tenant { id: string; allowedRegions: string[]; latencyBudgetMs: number }
interface RegionRoute { region: string; active: boolean }
function routePrompt(tenant: Tenant, candidates: string[]): string {
  // pick first allowed region with lowest observed latency
  return tenant.allowedRegions.find(r=>candidates.includes(r)) || candidates[0];
}
```

